#!/usr/bin/env python3
"""Regenerate catalog/UNVERIFIED.md from the catalog JSON files."""
import glob, json, os
CAT = os.path.join(os.path.dirname(__file__), '..', '..', 'catalog')
out = ['# Unverified & incomplete catalog entries', '',
       'Generated by `scripts/research/gen_unverified.py`. Do not edit by hand.', '',
       '**What `verified` means:** `true` = every number in the entry comes from the manufacturer\'s own spec page or datasheet '
       '(linked in `sourceUrl`). `false` = figures come from resellers, rack-vendor guides or typical values for generic items, '
       'or could not be confirmed. A `null` field means the value was not published or sources disagreed; it is never guessed.', '']
missing = []
for f in sorted(glob.glob(os.path.join(CAT, '*.json'))):
    if f.endswith('schema.json'):
        continue
    data = json.load(open(f))
    un = [p for p in data['parts'] if not p['verified']]
    if un:
        out += [f'## {os.path.basename(f)}: {len(un)} unverified', '', '| Part | Why |', '|---|---|']
        for p in un:
            why = (p.get('notes') or 'Not confirmed against a manufacturer source.').replace('|', '\\|')
            out.append(f"| `{p['id']}` {p['name']} | {why} |")
        out.append('')
    for p in data['parts']:
        gaps = [k for k, v in (('depth', p['depthMm']), ('weight', p['weightKg']),
                               ('power', p['power']['maxW'] if p['power']['maxW'] is not None else p['power']['typicalW']))
                if v is None and p['category'] not in ('blank', 'patch-panel', 'cable-management', 'shelf', 'mount', 'accessory')
                or (k == 'depth' and v is None)]
        if gaps:
            missing.append((os.path.basename(f), p['id'], ', '.join(sorted(set(gaps)))))
# Faceplate layouts that couldn't be fully confirmed.
lay = []
for f in sorted(glob.glob(os.path.join(CAT, '*.json'))):
    if f.endswith('schema.json'):
        continue
    for p in json.load(open(f))['parts']:
        L = p.get('layout')
        if L and not L.get('layoutVerified'):
            why = (L.get('notes') or 'Positions estimated; not confirmed against a manufacturer drawing.').replace('|', '\\|')
            src = ', '.join(f'[source]({u})' for u in L.get('sources', [])) or 'none (generic item)'
            lay.append(f"| `{p['id']}` {p['name']} | {why} | {src} |")
out += ['## Unverified faceplate layouts', '',
        'Detailed front/rear/top layouts with `layoutVerified: false`: counts come from the sources, but the face or position of some items '
        'could not be confirmed from a manufacturer spec sheet or drawing.', '', '| Part | What is not confirmed | Sources |', '|---|---|---|']
out += lay + ['']
out += ['## Missing values', '', 'Parts with `null` depth, weight or power (passive items are only listed for missing depth).', '',
        '| File | Part | Missing |', '|---|---|---|']
out += [f'| {f} | `{i}` | {g} |' for f, i, g in missing]
open(os.path.join(CAT, 'UNVERIFIED.md'), 'w').write('\n'.join(out) + '\n')
print(f'UNVERIFIED.md: {sum(1 for l in out if l.startswith("| `"))} unverified rows, {len(missing)} with missing values')
